 private sealed record Catalog(string Version,Dictionary<string,byte[]> Agent,Dictionary<string,byte[]> Setup);
 private readonly Lazy<Catalog> catalog=new(()=>{
  Dictionary<string,byte[]> Load(string group){var dir=Path.Combine(AppContext.BaseDirectory,"AgentTemplate",group);if(!Directory.Exists(dir))throw new InvalidOperationException(global::SysAdminAssistant.Core.ProductText.Get("Нет шаблона автообновления. Опубликуй сервер через PUBLISH.bat целиком."));var paths=Directory.GetFiles(dir);if(paths.Length>128)throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Слишком много файлов шаблона"));var result=new Dictionary<string,byte[]>();long total=0;foreach(var path in paths){var name=Path.GetFileName(path);if(!AgentRelease.FileName(name))continue;if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0||new FileInfo(path).Length>30000000)throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Неверный шаблон"));var bytes=File.ReadAllBytes(path);total+=bytes.Length;if(total>80000000)throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Шаблон слишком велик"));result.Add(name,bytes);}return result;}
  var agent=Load("Agent");var setup=Load("Setup");var version=AssemblyName.GetAssemblyName(Path.Combine(AppContext.BaseDirectory,"AgentTemplate","Agent","SysAdminAssistant.Agent.dll")).Version!.ToString();return new(version,agent,setup);
 });
 private sealed record RuntimeArtifact(byte[] Bytes,AgentReleaseFile Descriptor);
 private readonly Lazy<RuntimeArtifact?> windowsRuntime=new(()=>{
  var path=Path.Combine(AppContext.BaseDirectory,"AgentTemplate","Runtime",AgentDesktopRuntime.FileName);
  var file=new FileInfo(path);
  if(!file.Exists||(file.Attributes&FileAttributes.ReparsePoint)!=0||file.Length is <1 or >AgentDesktopRuntime.MaxBytes)return null;
  var bytes=File.ReadAllBytes(path);
  return AgentDesktopRuntime.MatchesMicrosoftPackage(bytes)?new RuntimeArtifact(bytes,new(bytes.LongLength,Convert.ToHexString(SHA256.HashData(bytes)))):null;
 });
 private static AgentRecord Authorize(AgentIndex s,AgentReleaseRequest r,string? scope=null,bool linux=false){if(r.Scope!=null&&r.Scope!=scope||r.AgentId==null||r.Signature==null||r.AgentId.Length!=32||r.Signature.Length>256||!Guid.TryParseExact(r.Nonce,"N",out _)||(r.Timestamp<DateTimeOffset.UtcNow.ToUnixTimeSeconds()-300||r.Timestamp>DateTimeOffset.UtcNow.ToUnixTimeSeconds()+300))throw new UnauthorizedAccessException(global::SysAdminAssistant.Core.ProductText.Get("Неверный запрос обновления"));var a=s.Agents.SingleOrDefault(a=>a.Id==r.AgentId&&a.Approved&&!a.Revoked&&(a.Platform=="Linux")==linux)??throw new UnauthorizedAccessException(global::SysAdminAssistant.Core.ProductText.Get("Агент не подтверждён или отозван"));using var cert=X509CertificateLoader.LoadCertificate(Convert.FromBase64String(a.Certificate));using var key=cert.GetECDsaPublicKey()!;if(cert.NotBefore.ToUniversalTime()>DateTime.UtcNow||!key.VerifyData(AgentRelease.Challenge(r),Convert.FromBase64String(r.Signature),HashAlgorithmName.SHA256))throw new UnauthorizedAccessException(global::SysAdminAssistant.Core.ProductText.Get("Подпись запроса обновления не принята"));return a;}
 public AgentSignedRelease Release(AgentReleaseRequest request)=>State<AgentSignedRelease>(s=>{var agent=Authorize(s,request,AgentRelease.WindowsRuntimeScope);var c=catalog.Value;Dictionary<string,AgentReleaseFile> Files(Dictionary<string,byte[]> files)=>files.ToDictionary(x=>x.Key,x=>new AgentReleaseFile(x.Value.LongLength,Convert.ToHexString(SHA256.HashData(x.Value))));var document=new AgentReleaseDocument(request.AgentId,request.Nonce,c.Version,DateTime.UtcNow.AddMinutes(10),Files(c.Agent),Files(c.Setup),SignTrust(s)){Runtime=AgentRelease.SupportsWindowsRuntime(request.Scope,agent.AgentVersion)?windowsRuntime.Value?.Descriptor:null};AgentRelease.Validate(document);var payload=JsonSerializer.Serialize(document,AgentWire.Json);using var ca=Ca(s);using var key=ca.GetECDsaPrivateKey()!;return new(payload,Convert.ToBase64String(key.SignData(AgentRelease.Content(payload),HashAlgorithmName.SHA256)));},true);
 public byte[] ReleaseFile(AgentReleaseDownload r)=>State(s=>{var agent=Authorize(s,r.Request,AgentRelease.WindowsRuntimeScope);if(!AgentRelease.FileName(r.Name))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Неверное имя файла"));if(r.Group=="Runtime"&&!AgentRelease.SupportsWindowsRuntime(r.Request.Scope,agent.AgentVersion))throw new UnauthorizedAccessException("Агент не поддерживает получение установщика .NET.");if(r.Group=="Runtime")return r.Name==AgentDesktopRuntime.FileName&&windowsRuntime.Value is {} artifact?artifact.Bytes:throw new ArgumentException("Установщик .NET не включён в серверный комплект.");var files=r.Group switch{"Agent"=>catalog.Value.Agent,"Setup"=>catalog.Value.Setup,_=>throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Неверная группа"))};return files.TryGetValue(r.Name,out var bytes)?bytes:throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Файл не найден в выпуске"));});
}
